// Discover BrighterMonday job URLs from listing pages 1-5
const base = 'https://www.brightermonday.co.ke/jobs';
const pageUrls = [base, ...Array.from({ length: 4 }, (_, i) => `${base}?page=${i + 2}`)];
const headers = {
  'User-Agent': 'Mozilla/5.0 (compatible; CareerSasaBot/1.0; +https://careersasa.co.ke)',
  'Accept': 'text/html,application/xhtml+xml',
};

const seen = new Set();
for (const url of pageUrls) {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url,
    headers,
    timeout: 30000,
    returnFullResponse: false,
  });
  const html = typeof response === 'string' ? response : String(response);
  const pattern = /\/listings\/[a-z0-9-]+/gi;
  let match;
  while ((match = pattern.exec(html)) !== null) {
    seen.add('https://www.brightermonday.co.ke' + match[0]);
  }
}

const jobs = Array.from(seen).map(jobUrl => ({ json: { jobUrl } }));
console.log(`Discovered ${jobs.length} unique BrighterMonday jobs from ${pageUrls.length} pages`);
return jobs;

// Parse schema.org JobPosting JSON-LD from the detail page
const jobUrl = $('Split In Batches').item.json.jobUrl;
const html = typeof $input.item.json.data === 'string'
  ? $input.item.json.data
  : ($input.item.json.body || '');

function cleanText(text) {
  if (!text) return null;
  return String(text).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim() || null;
}

function findById(graph, id) {
  if (!id || !Array.isArray(graph)) return null;
  return graph.find(n => n && n['@id'] === id) || null;
}

function resolveRef(graph, value) {
  if (!value) return null;
  if (typeof value === 'string') return findById(graph, value);
  if (value['@id'] && Object.keys(value).length === 1) return findById(graph, value['@id']) || value;
  return value;
}

const ldMatch = html.match(/<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/i);
if (!ldMatch) {
  return { json: { skip: true, reason: 'No JSON-LD', jobUrl } };
}

let payload;
try {
  payload = JSON.parse(ldMatch[1]);
} catch (e) {
  return { json: { skip: true, reason: 'Invalid JSON-LD', jobUrl } };
}

const graph = Array.isArray(payload['@graph'])
  ? payload['@graph']
  : (Array.isArray(payload) ? payload : [payload]);

const posting = graph.find(n => n && (n['@type'] === 'JobPosting' || (Array.isArray(n['@type']) && n['@type'].includes('JobPosting'))));
if (!posting) {
  return { json: { skip: true, reason: 'No JobPosting', jobUrl } };
}

const org = resolveRef(graph, posting.hiringOrganization);
const place = resolveRef(graph, posting.jobLocation);
const address = place ? (resolveRef(graph, place.address) || place.address || {}) : {};

const salary = posting.baseSalary || {};
const salaryValue = salary.value || {};
const experience = posting.experienceRequirements || {};
const months = typeof experience.monthsOfExperience === 'number'
  ? experience.monthsOfExperience
  : null;

const company = cleanText(org?.name || org?.legalName) || 'Company Name Not Available';
const locationParts = [
  cleanText(address.addressLocality),
  cleanText(address.addressRegion),
  cleanText(address.addressCountry)
].filter(Boolean);
const location = [...new Set(locationParts)].join(', ') || 'Kenya';

const employmentRaw = Array.isArray(posting.employmentType)
  ? posting.employmentType[0]
  : posting.employmentType;

return {
  json: {
    skip: false,
    jobUrl,
    title: cleanText(posting.title) || 'Untitled Position',
    company,
    location,
    description: posting.description || '',
    employmentType: employmentRaw || 'FULL_TIME',
    industry: cleanText(posting.industry),
    occupationalCategory: cleanText(posting.occupationalCategory),
    qualifications: cleanText(posting.qualifications),
    datePosted: posting.datePosted || null,
    validThrough: posting.validThrough || null,
    salaryCurrency: salary.currency || 'KES',
    salaryMin: salaryValue.minValue ?? salaryValue.value ?? null,
    salaryMax: salaryValue.maxValue ?? salaryValue.value ?? null,
    salaryPeriod: salaryValue.unitText || 'MONTH',
    minimumExperienceYears: months != null ? Math.round(months / 12) : null,
    directApply: Boolean(posting.directApply),
    addressLocality: cleanText(address.addressLocality),
    addressRegion: cleanText(address.addressRegion),
    addressCountry: cleanText(address.addressCountry) || 'Kenya'
  }
};

// Transform JSON-LD fields into the CareerSasa jobs schema
const item = $input.item.json;
if (item.skip) {
  console.log(`Skipping ${item.jobUrl}: ${item.reason}`);
  return { json: { skipped: true, jobUrl: item.jobUrl, reason: item.reason } };
}

function parseEmploymentType(type) {
  if (!type) return 'FULL_TIME';
  const t = String(type).toUpperCase().replace(/[\s-]+/g, '_');
  if (t.includes('PART')) return 'PART_TIME';
  if (t.includes('CONTRACT')) return 'CONTRACTOR';
  if (t.includes('INTERN')) return 'INTERN';
  if (t.includes('TEMP')) return 'TEMPORARY';
  if (t.includes('VOLUNTEER')) return 'VOLUNTEER';
  if (t.includes('FULL')) return 'FULL_TIME';
  return 'FULL_TIME';
}

function toIso(value) {
  if (!value) return null;
  const d = new Date(value);
  return Number.isNaN(d.getTime()) ? null : d.toISOString();
}

const kenyanCounties = [
  'Nairobi', 'Mombasa', 'Kisumu', 'Nakuru', 'Kiambu', 'Machakos',
  'Kajiado', 'Kilifi', 'Kwale', 'Uasin Gishu', 'Kisii', 'Nyeri'
];

let county = null;
const haystack = `${item.addressLocality || ''} ${item.addressRegion || ''} ${item.location || ''}`;
for (const c of kenyanCounties) {
  if (haystack.toLowerCase().includes(c.toLowerCase())) {
    county = c;
    break;
  }
}

const salaryMin = typeof item.salaryMin === 'number' ? item.salaryMin : null;
const salaryMax = typeof item.salaryMax === 'number' ? item.salaryMax : null;
const hasSalary = salaryMin != null || salaryMax != null;


function resolveApply(jobUrl, description) {
  const boardHosts = ['brightermonday.co.ke'];
  const blocked = new Set([...boardHosts, 'facebook.com','twitter.com','x.com','linkedin.com','instagram.com','youtube.com','whatsapp.com','googletagmanager.com']);
  const text = String(description || '').replace(/<[^>]+>/g, ' ');
  const emails = [];
  const emailRe = /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi;
  let m;
  while ((m = emailRe.exec(text)) !== null) {
    const email = m[0].toLowerCase();
    const domain = email.split('@')[1] || '';
    if (email.startsWith('anonymous@') || boardHosts.some(h => domain === h || domain.endsWith('.' + h))) continue;
    if (!emails.includes(email)) emails.push(email);
  }
  const urls = [];
  const urlRe = /https?:\/\/[^\s<>"')]+/gi;
  while ((m = urlRe.exec(text)) !== null) {
    let url = m[0].replace(/[),.;]+$/g, '');
    try {
      const host = new URL(url).hostname.replace(/^www\./,'').toLowerCase();
      if ([...blocked].some(b => host === b || host.endsWith('.' + b))) continue;
      if (!urls.includes(url)) urls.push(url);
    } catch {}
  }
  if (urls[0]) return { application_url: urls[0], apply_link: urls[0], apply_email: emails[0] || null };
  if (emails[0]) return { application_url: null, apply_link: null, apply_email: emails[0] };
  return { application_url: jobUrl, apply_link: null, apply_email: null };
}

const apply = resolveApply(item.jobUrl, item.description);

const transformedJob = {
  title: item.title,
  company: item.company,
  location: item.location,
  description: item.description || '',
  apply_link: apply.apply_link,
  apply_email: apply.apply_email,
  application_url: apply.application_url,
  direct_apply: false,
  employment_type: parseEmploymentType(item.employmentType),
  job_location_type: 'ON_SITE',
  job_location_country: 'Kenya',
  job_location_county: county,
  job_location_city: item.addressLocality || county,
  salary: hasSalary
    ? `${item.salaryCurrency || 'KES'} ${salaryMin || ''}${salaryMax && salaryMax !== salaryMin ? ` - ${salaryMax}` : ''} / ${(item.salaryPeriod || 'MONTH').toLowerCase()}`
    : null,
  salary_currency: item.salaryCurrency || 'KES',
  salary_min: salaryMin,
  salary_max: salaryMax,
  salary_period: item.salaryPeriod || 'MONTH',
  salary_visibility: hasSalary ? 'Show' : 'Hide',
  date_posted: toIso(item.datePosted) || new Date().toISOString(),
  valid_through: toIso(item.validThrough),
  source: 'Scraper',
  status: 'active',
  posted_by: 'admin',
  identifier: item.jobUrl,
  hiring_organization_name: item.company,
  industry: item.industry,
  experience_level: item.qualifications,
  minimum_experience: item.minimumExperienceYears,
  tags: [item.occupationalCategory, item.industry, 'brightermonday'].filter(Boolean).join(', '),
  views_count: 0,
  applications_count: 0,
  google_indexed: false,
  is_featured: false
};

return { json: transformedJob };

const allItems = $input.all();
const upserted = allItems.filter(item => item.json.id).length;
const skipped = allItems.filter(item => item.json.skipped).length;
const summary = {
  timestamp: new Date().toISOString(),
  totalItems: allItems.length,
  successfulInserts: upserted,
  skipped,
  source: 'brightermonday.co.ke'
};
console.log('BrighterMonday scraping summary:', summary);
return { json: summary };
